from typing import Callable, Sequence, TypeVar

T = TypeVar("T")

def finite_functor_category_argmin(
    candidates: Sequence[T], loss: Callable[[T], float]
) -> tuple[T, float]:
    """Return the first loss-minimizing candidate in a nonempty sequence."""
    if not candidates:
        raise ValueError("at least one candidate is required")
    best = candidates[0]
    best_loss = loss(best)
    for candidate in candidates[1:]:
        value = loss(candidate)
        if value < best_loss:
            best, best_loss = candidate, value
    return best, best_loss

from math import sqrt
from typing import Callable, Sequence

Vector = tuple[float, ...]

def euclidean_norm(x: Sequence[float]) -> float:
    return sqrt(sum(value * value for value in x))

def sampled_residual_certificate(
    residual: Callable[[Vector], Vector],
    samples: Sequence[tuple[Vector, Vector]],
    k: float,
) -> list[tuple[float, float, bool]]:
    """Compare sampled residual-block ratios with the theorem's 1 + k bound."""
    if k < 0:
        raise ValueError("k must be nonnegative")
    results: list[tuple[float, float, bool]] = []
    for x, y in samples:
        if len(x) != len(y):
            raise ValueError("sample vectors must have matching dimensions")
        rx, ry = residual(x), residual(y)
        delta = tuple(a - b for a, b in zip(x, y))
        block_delta = tuple(
            dx + (a - b) for dx, a, b in zip(delta, rx, ry)
        )
        denominator = euclidean_norm(delta)
        ratio = 0.0 if denominator == 0.0 else euclidean_norm(block_delta) / denominator
        results.append((ratio, 1.0 + k, ratio <= 1.0 + k + 1e-12))
    return results
